/**
 * @description
 * 本脚本用于 n8n 的 "Code" 节点。
 * 功能：接收一个包含 XML/HTML 风格标签的文章内容，将其转换为 Hugo 静态网站生成器所需的 Markdown 文件格式。
 * 这个版本使用正则表达式解析标签，并增加了调试日志和改进的文件名生成机制。
 * 增加了对关键字段缺失的容错处理，遇到错误时不再中断工作流，而是返回一个带有错误标记的 Item。
 * v3: 增加了对 <img_url> 标签的处理，使用 featured_image 字段，如果为空则提供随机默认图片。
 * v4: (当前版本) 优化了图片处理逻辑，使其能够优先读取顶层的 `$json.img_url` 字段，如果该字段不存在，则回退到解析 <img_url> 标签。
 * v5: (新版本) 增加文件名生成健壮性检查，如果文件名不合法或为空，则跳过当前 Item 的文件生成，返回错误信息。
 *
 * 输入：上一个节点传递过来的数据项，其中应包含一个名为 `content` 的字段，或一个名为 `img_url` 的顶层字段。
 *
 * 输出：一个包含三部分的新对象（或包含错误信息的对象）：
 * 1. `title`: 提取出的文章标题。
 * 2. `hugo_article`: 格式化后的完整 Hugo 文章字符串。
 * 3. `fileName`: 根据文章标题、时间戳和项目索引生成的唯一文件名。
 * 或：
 * 1. `error`: 错误消息。
 * 2. `itemIndex`: 出错的 Item 索引。
 * 3. `originalId`: 原始数据的 ID (如果存在)。
 */

// --- 1. 数据准备 ---

const rawContentString = $json.content;
const itemIndex = $itemIndex; // 方便在各处使用

// 检查输入是否为空或非字符串 (主要针对基于标签的解析)
if (!rawContentString || typeof rawContentString !== 'string') {
  // 即使 content 为空，如果顶层有其他字段（如 title, img_url），可能仍需处理，因此这里仅作警告。
  // 但是，如果后续依赖 rawContentString 的关键字段无法提取，仍然会跳过。
  console.warn(`[Item Index: ${itemIndex}] 输入字段 'content' 为空或不是字符串。`);
}

// --- 2. 健壮的 Tag 解析 ---

let articleData = {}; // 初始化为空对象，确保总是有一个对象
let hasParsingError = false;
let parsingErrorMessage = '';

try {
  const extractFromTag = (tagName, content) => {
    // 检查 content 是否有效，防止在 null 或 undefined 上调用 match
    if (!content || typeof content !== 'string') return '';
    // 稍微改进正则，处理可能的属性和更宽松的空白
    const regex = new RegExp(`<${tagName}[^>]*>\\s*([\\s\\S]*?)\\s*<\\/${tagName}>`, 'is');
    const match = content.match(regex);
    return match && match[1] ? match[1].trim() : '';
  };

  const title = extractFromTag('title', rawContentString);
  const article_content = extractFromTag('article_content', rawContentString);
  const summary = extractFromTag('summary', rawContentString);
  const tagsString = extractFromTag('tags', rawContentString);
  const mainTopicsString = extractFromTag('main_topics', rawContentString);

  const img_url = $json.img_url || extractFromTag('img_url', rawContentString);

  console.log(`[Item Index: ${itemIndex}] 提取到的标题 (Title):`, title);

  const tags = tagsString ? tagsString.split(',').map(tag => tag.trim()).filter(Boolean) : [];
  const main_topics = mainTopicsString ? mainTopicsString.split(',').map(topic => topic.trim()).filter(Boolean) : [];

  articleData = {
    title,
    summary,
    tags,
    main_topics,
    article_content,
    img_url, 
  };

} catch (e) {
  hasParsingError = true;
  parsingErrorMessage = `Tag 解析失败: ${e.message}.`;
  console.error(`[Item Index: ${itemIndex}] Tag 解析格式内容失败:`, e);
}

// 如果解析 Tag 时发生错误，直接返回错误 Item
if (hasParsingError) {
    return {
        json: {
            error: parsingErrorMessage,
            itemIndex: itemIndex,
            originalId: $json.id || $json.articleId || 'N/A',
            // 标记此 Item 为跳过，以便下游节点可以过滤
            skip: true 
        }
    };
}

// --- 3. 提取并验证内容 ---

const {
  title,
  summary,
  tags,
  main_topics,
  article_content,
  img_url, 
} = articleData; 

// 检查关键字段 article_content 是否存在
if (!article_content || article_content.trim() === '') { // 增加对空字符串的检查
  console.error(`[Item Index: ${itemIndex}] 错误: 解析后的数据缺少必要的 <article_content> 内容或内容为空。跳过此 Item。`);
  return {
       json: {
           error: `缺少 <article_content> 内容`,
           itemIndex: itemIndex,
           originalId: $json.id || $json.articleId || 'N/A',
           skip: true
       }
  };
}

// 警告非关键字段缺失
if (!title || title.trim() === '') { // 增加对空字符串的检查
  console.warn(`[Item Index: ${itemIndex}] 警告: 提取到的文章标题为空。文件名将使用默认前缀。Front Matter 中的 title 也会为空。`);
}

// --- 4. 构建 Hugo Front Matter (YAML 格式) ---

const getISODateWithTimezone = (date) => {
    const pad = (num) => (num < 10 ? '0' : '') + num;
    const offset = -date.getTimezoneOffset();
    const sign = offset >= 0 ? '+' : '-';
    const hours = pad(Math.floor(Math.abs(offset) / 60));
    const minutes = pad(Math.abs(offset) % 60);
    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}${sign}${hours}:${minutes}`;
};
const hugoDate = getISODateWithTimezone(new Date());

const toYamlString = (value) => {
    if (value === undefined || value === null) return '""';
    if (typeof value === 'string') {
      // 检查是否包含 YAML 特殊字符或以特殊字符开头
      // 对于多行字符串，YAML 建议使用 | 或 >，这里简单处理，若包含换行符也进行字符串化
      if (/[":,\-#{}[]|>]/g.test(value) || value.startsWith('---') || value.startsWith('#') || value.includes('\n')) {
           return JSON.stringify(value); // 使用 JSON.stringify 来安全地处理包含特殊字符的字符串
      }
      return value;
    }
    return JSON.stringify(value); // 其他类型直接 JSON.stringify
};

const toYamlList = (arr) => {
    if (!Array.isArray(arr) || arr.length === 0) return '[]';
    // 确保每个列表项都是安全的 YAML 字符串
    return '\n' + arr.map(item => `  - ${toYamlString(item)}`).join('\n');
}

// 决定最终使用的图片路径
let finalImage = img_url; // 使用一个新变量名以示清晰
if (!finalImage || finalImage.trim() === '') { // 增加对空字符串的检查
  // 如果 img_url 为空，则生成一个 1 到 20 之间的随机数
  const randomNumber = Math.floor(Math.random() * 20) + 1;
  finalImage = `images/default (${randomNumber}).png`;
  console.log(`[Item Index: ${itemIndex}] 'img_url' is empty or blank. Using default image: ${finalImage}`);
}

const frontMatter = `---
title: ${toYamlString(title || 'Untitled Article')}
date: ${hugoDate}
draft: false
featured_image: ${toYamlString(finalImage)}
summary: ${toYamlString(summary || '')}
tags: ${toYamlList(tags)}
main_topics: ${toYamlList(main_topics)}
---
`;

// --- 5. 组合并返回最终结果 ---

const hugoArticle = frontMatter + '\n' + article_content;

const generateBasicSlug = (str) => {
  if (!str || typeof str !== 'string') return '';
  return str
    .toString()
    .normalize('NFD') // Normalization Form D (Canonical Decomposition)
    .replace(/[\u0300-\u036f]/g, '') // Remove diacritics
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-') // Replace spaces with -
    .replace(/[^\w-]+/g, '') // Remove all non-word chars except hyphens
    .replace(/--+/g, '-'); // Replace multiple - with single -
}

const generateUniqueFilename = (originalTitle, itemIndex) => {
  const now = new Date();
  const year = now.getFullYear();
  const month = (now.getMonth() + 1).toString().padStart(2, '0');
  const day = now.getDate().toString().padStart(2, '0');
  const hours = now.getHours().toString().padStart(2, '0');
  const minutes = now.getMinutes().toString().padStart(2, '0');
  const seconds = now.getSeconds().toString().padStart(2, '0');
  const milliseconds = now.getMilliseconds().toString().padStart(3, '0');
  const timestamp = `${year}${month}${day}${hours}${minutes}${seconds}${milliseconds}`;
  let baseName = '';
  // 确保 originalTitle 是有效字符串
  if (originalTitle && typeof originalTitle === 'string' && originalTitle.trim() !== '') {
    baseName = generateBasicSlug(originalTitle);
  }

  // 增加更严格的 basename 检查，防止生成空或过短的 slug
  const MIN_SLUG_LENGTH = 3;
  if (!baseName || baseName.length < MIN_SLUG_LENGTH) {
    baseName = 'article'; // 如果标题无法生成有效 slug，使用默认值
  }

  // 截断 basename 以避免文件名过长，并处理尾部连字符
  const MAX_BASENAME_LENGTH = 50;
  if (baseName.length > MAX_BASENAME_LENGTH) {
    let truncatedBaseName = baseName.substring(0, MAX_BASENAME_LENGTH);
    const lastHyphen = truncatedBaseName.lastIndexOf('-');
    // 如果截断位置附近有连字符，优先截到连字符处
    if (lastHyphen !== -1 && lastHyphen > MAX_BASENAME_LENGTH * 0.8) { // 例如，在 80% 到 100% 之间
        baseName = truncatedBaseName.substring(0, lastHyphen);
    } else {
        baseName = truncatedBaseName;
    }
    // 移除可能存在的尾部连字符
    baseName = baseName.replace(/-$/, '');
  }

  // 最终文件名格式
  return `${baseName}-${timestamp}-${itemIndex}.md`;
};

const finalFileName = generateUniqueFilename(title, itemIndex);

// --- *** 关键的健壮性检查部分 START *** ---
// 检查生成的文件名是否为空或不符合基本文件命名规范
// 一个有效的文件名至少应该包含一些字符和扩展名，这里简单检查非空和是否包含 ".md"
if (!finalFileName || typeof finalFileName !== 'string' || finalFileName.trim() === '' || !finalFileName.endsWith('.md')) {
    const errorMsg = `文件名生成失败或不合法: '${finalFileName}'。跳过此 Item 的文件生成。`;
    console.error(`[Item Index: ${itemIndex}] 错误: ${errorMsg}`);
    return {
        json: {
            error: errorMsg,
            itemIndex: itemIndex,
            originalId: $json.id || $json.articleId || 'N/A',
            // 明确标记此 Item 为跳过，以便下游节点可以过滤它
            skip: true 
        }
    };
}
// --- *** 关键的健壮性检查部分 END *** ---

console.log(`[Item Index: ${itemIndex}] 生成的文件名: ${finalFileName}`);

// 正常返回数据
return {
  json: {
    title: title || 'Untitled Article', // 确保 title 至少有一个默认值
    hugo_article: hugoArticle,
    fileName: finalFileName,
    articleId: $json.id || $json.articleId || 'N/A'
  }
};

/**
 * @description 检查文件写入是否成功
 * 通过检查Execute Command节点的执行结果判断
 * @returns {Object} 包含成功状态和相关信息的对象
 */
function checkWriteSuccess() {
  const writeResult = $json;

  // Execute Command节点成功时会返回执行信息
  const success = writeResult && (writeResult.exitCode === 0 || writeResult.exitCode === undefined);

  return {
    success: success,
    fileName: $('生成Hugo内容').item.json.fileName,
    articleId: $('生成Hugo内容').item.json.articleId,
    title: $('生成Hugo内容').item.json.title,
    filePath: `/app/hugo/hugo/content/articles/${$('生成Hugo内容').item.json.fileName}`,
    error: success ? null : '文件写入失败',
    exitCode: writeResult.exitCode || 0
  };
}

return checkWriteSuccess();

/**
 * @description 记录同步失败的文章
 * 用于错误处理和日志记录
 * @returns {Object} 包含失败信息的对象
 */
function logSyncFailure() {
  const data = $json;

  return {
    articleId: data.articleId || $('生成Hugo内容').item.json.articleId,
    title: data.title || $('生成Hugo内容').item.json.title,
    error: data.error || data.message || '未知错误',
    timestamp: new Date().toISOString(),
    status: 'sync_failed'
  };
}

return logSyncFailure();

/**
 * @description 更新单篇文章的同步状态
 * 为每篇成功同步的文章更新状态
 * @returns {Object} 包含文章同步状态信息的对象
 */
function updateSyncStatus() {
  const data = $json;

  return {
    articleId: $('生成Hugo内容').item.json.articleId,
    title: $('生成Hugo内容').item.json.title,
    fileName: $('生成Hugo内容').item.json.fileName,
    syncTime: new Date().toISOString(),
    status: 'synced_to_hugo'
  };
}

return updateSyncStatus();
